if('serviceWorker' in navigator) {
    navigator.serviceWorker
        .register('sw.js')
        .then(function() { console.log('Service Worker Registered'); });
}

const noSleep = new NoSleep();

const wrapper = document.getElementsByClassName("wrapper")[0];
const timer = document.getElementById("footer");
const container = document.getElementById("container");

let interval;
let vibrateInterval; 

let seconds = 0;
let clickCount = 0;

let words;

addInGameEvents();
loadWordList("words0.js");

//resize
document.getElementById("container").style.height = "calc(" + window.innerHeight + "px - 151px)";
window.addEventListener('resize', function() {
    document.getElementById("container").style.height = "calc(" + window.innerHeight + "px - 151px)";
});

function addInGameEvents() {
    wrapper.addEventListener("click", clickEvents);
    window.onclick = function() {
        noSleep.enable();
        window.onclick = null;
    }
    document.getElementById("cardPackSelect").addEventListener("change", onCardPackSelect);
}
function loadWordList(listName) {
    console.log("loading: " + listName);
    import('./words/js/' + listName)
        .then(obj => words = obj.default)
        .catch(err => errorLoadWordList(err));
}
function  errorLoadWordList(error) {
    import('./words/js/words0.js')
        .then(obj => words = obj.default)
        .catch(err => console.log(error + " | " + err));
}
function onCardPackSelect() {
    loadWordList(this.value);
}


function clickEvents(e) {
    if(clickCount == 0) {
        var word = words.splice(Math.floor(Math.random() * words.length), 1);
        
        if (word.length == 0) { 
            word = "Du hast alle Karten gespielt!"; 
        }
        container.innerHTML = word;
        setRandomColor();
        $(container).fadeTo(250, 1);

        timer.innerHTML = "> 01:00 <";
        seconds = 0;

        if('vibrate' in navigator)
            window.navigator.vibrate(100);
    }
    else if(clickCount == 1) {
        timer.innerHTML = "01:00";
        interval = setInterval(timerFunction, 1000); // Timer Countdown Start
        
        if('vibrate' in navigator)
            window.navigator.vibrate(300);
    }
    else {
        $(container).fadeTo(250, 0);

        clearInterval(interval); // Timer Stop
        clearInterval(vibrateInterval); // End Vibrate Stop

        clickCount = 0;
        return;
    }
    clickCount = clickCount + 1;
}

function timerFunction() {
    seconds = seconds + 1;
    var leftSeconds = 60 - seconds;
    timer.innerHTML = secondsToTimeString(leftSeconds);

    if(seconds == 30) {
        window.navigator.vibrate(1000); 
        beep();
    }

    if(seconds > 60 - 1) {
        timerEndVibrate();
    }
}
function timerEndVibrate() {
    window.navigator.vibrate(200);
    timer.innerHTML = secondsToTimeString(seconds);
    seconds = 0;
    clearInterval(interval);
    vibrateInterval = setInterval(function() { 
        navigator.vibrate(200); 
        beep(); 
    }, 600);
}

function randomHsl() {
    return 'hsla(' + (Math.random() * 360) + ', 100%, 10%, 1)';
}

function setRandomColor() {
    document.body.style = "background-color: " + randomHsl();
}

function secondsToTimeString(seconds) {
    var minutes = Math.floor(seconds / 60);
    return str_pad_left(minutes,'0', 2)+':'+str_pad_left(seconds - minutes * 60,'0',2)
}
function str_pad_left(string,pad,length) {
    return (new Array(length+1).join(pad)+string).slice(-length);
}

function beep() {
    var snd = new Audio("data:audio/wav;base64,");  
    snd.play();
}